// ---------- Node-RED Function: MQTT → InfluxDB v1.x ----------
//
// Input examples:
// meteorcams/nz0014/nextcapstart : "2025-10-26 07:11:02.642132 UTC"
// meteorcams/nz001p/meteorcount  : 123
//
// Output for InfluxDB v1.x Out node:
//   msg.measurement = "1month.meteor_messages"
//   msg.payload = [
//       { value_num: 123 },                       // fields object
//       { topic: "meteorcams/nz001p/meteorcount" } // tags object
//   ]
//
// ------------------------------------------------------------

let topic = msg.topic || "";

// Normalise to lowercase, keep the FULL topic path
let topicTag = topic.toLowerCase();

// Build the fields object
let fields = {};
if (typeof msg.payload === "number" || (!isNaN(msg.payload) && msg.payload !== "")) {
    fields.value_num = Number(msg.payload);
} else {
    fields.value_str = String(msg.payload);
}

// Build the tags object
let tags = { topic: topicTag };

// Assign measurement and payload array
msg.measurement = "meteor_messages";
msg.payload = [fields, tags];

return msg;

// updateLastSeen.js
// Called on every MQTT message from meteorcams/#
let match = msg.topic.match(/nz[0-9a-z]+/i);
if (!match) return null;

let id = match[0].toUpperCase();
let lastSeen = flow.get("lastSeen") || {};
lastSeen[id] = Date.now();
flow.set("lastSeen", lastSeen);

// optional: for debugging only
// node.status({text:`${id} seen @ ${new Date().toLocaleTimeString()}`});
return null;

const now = Date.now();
const THRESHOLD = 30 * 60 * 1000;   // 30 minutes of silence
const REMIND_INTERVAL = 60 * 60 * 1000; // 1 hour repeat

const lastSeen = flow.get("lastSeen") || {};
let lastAlert = flow.get("lastAlert") || {};

let missing = [];
for (let [id, t] of Object.entries(lastSeen)) {
    let minsAgo = ((now - t) / 60000).toFixed(1);

    // device is late
    if (now - t > THRESHOLD) {
        let lastAlertTime = lastAlert[id] || 0;

        // only alert if never alerted before or an hour has passed
        if (now - lastAlertTime > REMIND_INTERVAL) {
            missing.push(`${id} (last seen ${minsAgo} min ago)`);
            lastAlert[id] = now;  // record alert time
        }
    } else {
        // device is reporting again → clear its alert record
        delete lastAlert[id];
    }
}

// store updated alert state
flow.set("lastAlert", lastAlert);

if (missing.length > 0) {
    msg.topic = "MeteorCam Offline Alert. Full power outage";
    msg.payload = `Devices offline >30 min:\n${missing.join("\n")}`;
    return msg; // send one email
}
return null;

// ---------- Node-RED Function: Grouped Camera Offline Email Alert ----------
// Expects topics like: meteorcams/nz0014/camerastatus with payload "1" or "0"
// First alert after 10 min offline, then every 60 min while still offline
// --------------------------------------------------------------------------

const OFFLINE_DELAY = 10 * 60 * 1000;   // ✅ 10 minutes
const REMIND_INTERVAL = 60 * 60 * 1000; // 60 minutes

const topic = msg.topic || "";
const payload = String(msg.payload).trim();
const match = topic.match(/^meteorcams\/([0-9a-z]+)\/camerastatus$/i);
if (!match) return null; // ignore unrelated topics

const id = match[1].toUpperCase();
const now = Date.now();

// --- store latest status ---
let statusMap = flow.get("cameraStatus") || {};
statusMap[id] = { value: payload, lastUpdate: now };
flow.set("cameraStatus", statusMap);

// timers are global for the flow (we alert on *any* offline camera)
let offlineTimer = flow.get("offlineTimer");
let remindTimer  = flow.get("remindTimer");

// Helper: build & send ONE email listing all offline cams
function sendGroupedEmail(label) {
    const sMap = flow.get("cameraStatus") || {};
    const now = Date.now();
    let offline = [];

    for (const [cam, info] of Object.entries(sMap)) {
        if (info.value === "0") {
            const minsAgo = ((now - info.lastUpdate) / 60000).toFixed(1);
            offline.push(`${cam} (last seen ${minsAgo} min ago)`);
        }
    }

    if (offline.length > 0) {
        node.send({
            topic: `Cameras offline >${label}`,
            payload: offline.join("\n")
        });
    }
}

// ---------- Handle incoming status ----------
if (payload === "0") {
    // if this is the first offline camera, start the 10-min timer
    if (!offlineTimer && !remindTimer) {
        offlineTimer = setTimeout(() => {
            // after 10 mins, check again which are offline and send ONE email
            sendGroupedEmail("10 min");

            // then repeat every 60 mins
            remindTimer = setInterval(() => {
                sendGroupedEmail("60 min");
            }, REMIND_INTERVAL);

            flow.set("remindTimer", remindTimer);
        }, OFFLINE_DELAY);

        flow.set("offlineTimer", offlineTimer);
    }
}
else if (payload === "1") {
    // a camera came back online — check if ANY are still offline
    const anyOffline = Object.values(statusMap).some(s => s.value === "0");
    if (!anyOffline) {
        // all back online → stop timers
        if (offlineTimer) clearTimeout(offlineTimer);
        if (remindTimer) clearInterval(remindTimer);
        flow.set("offlineTimer", null);
        flow.set("remindTimer", null);
    }
}

return null;

// ---------- Node-RED Function: Zero Starcount During Daylight ----------
//
// This node runs *after* the MQTT→Influx function.
// If the topic ends in "/starcount" AND flow.get("daytime") is true,
// the numeric value is forced to 0 before writing to InfluxDB.
//
// Expects msg.payload = [fields, tags]
// ------------------------------------------------------------

const isDaytime = flow.get("daytime") === true;

if (Array.isArray(msg.payload) && msg.payload.length >= 2) {
    const fields = msg.payload[0];
    const tags = msg.payload[1];
    const topic = tags?.topic || "";

    if (isDaytime && /\/starcount$/i.test(topic)) {
        // Only modify starcount values during daylight
        if ("value_num" in fields) {
            fields.value_num = 0;
        }
    }

    msg.payload[0] = fields;
}

return msg;

// ---------- Node-RED Function: Split camerastatus topics to 2 outputs ----------
//
// Input: from MQTT → InfluxDB v1.x formatter
//   msg.measurement = "live_messages"
//   msg.payload = [
//       { value_num: 1 },
//       { topic: "meteorcams/nz0014/camerastatus" }
//   ]
//
// Output 1 → all normal topics (non-camerastatus)
// Output 2 → camerastatus topics only
//
// ------------------------------------------------------------------------------

let tags = msg.payload?.[1] || {};
let topic = tags.topic || "";

// clone the message so both branches can reuse safely if needed
let normalMsg = RED.util.cloneMessage(msg);
let statusMsg = RED.util.cloneMessage(msg);

// test for camerastatus suffix
if (/\/camerastatus$/i.test(topic)) {
    // route to Output 2 only
    statusMsg.measurement = "camera_status_messages";
    return [null, statusMsg];
} else {
    // route to Output 1 only
    normalMsg.measurement = "live_messages";
    return [normalMsg, null];
}

// Expecting msg.payload as an array of { time, value, topic }
let data = msg.payload || [];

// Read daytime flag (set by your time-range + Change nodes)
const isDaytime = flow.get("daytime") === true;

// Extract alphanumeric camera ID (e.g. NZ0014, NZ001P, NZ002K)
function extractCameraID(topic) {
    let match = topic?.match(/nz[0-9a-z]+/i);
    return match ? match[0].toUpperCase() : (topic || "UNKNOWN");
}

let grouped = {};
let latestGlobalTime = 0;

for (let entry of data) {
    if (!entry) continue;

    const id = extractCameraID(entry.topic);
    const t  = new Date(entry.time).getTime();
    let val  = Number(entry.value_num);

    if (!Number.isFinite(val) || !Number.isFinite(t)) continue;

    // 🔸 Force starcount to 0 during daytime
    // (only when the metric is starcount; other metrics unaffected)
    if (isDaytime && /\/starcount$/i.test(entry.topic)) {
       val = 0;
    }

    if (!grouped[id]) grouped[id] = { sum: 0, count: 0, latestVal: val, latestTime: t };

    grouped[id].sum += val;
    grouped[id].count += 1;

    if (t > grouped[id].latestTime) {
        grouped[id].latestVal = val;
        grouped[id].latestTime = t;
    }
    if (t > latestGlobalTime) latestGlobalTime = t;
}

// Prepare chart data arrays
const labels   = Object.keys(grouped).sort();
const averages = labels.map(id => grouped[id].count ? grouped[id].sum / grouped[id].count : 0);
let latests    = labels.map(id => grouped[id].latestVal);

// Format for Node-RED bar chart
msg.payload = [{
    series: ['Average (1h)', 'Latest value'],
    data: [averages, latests],
    labels: labels
}];

// Extra info for debugging / dashboard text node
msg.lastUpdate = latestGlobalTime ? new Date(latestGlobalTime).toLocaleString() : '';
// msg.daytime = isDaytime;

return msg;

// ---------- Node-RED Function: Starcount Line Chart (Zero During Daylight) ----------
//
// Expects msg.payload = array of { time, value_num, topic }
// Example topic: meteorcams/nz0014/starcount
//
// Uses flow variable "daytime" (boolean) to force starcount = 0 during daytime.
//
// Output format (for line/scatter chart):
//   msg.payload = [
//       {
//           series: ["NZ0014", "NZ001P", ...],
//           data: [ [ {x:time,y:value}, ... ], [ ... ], ... ],
//           labels: []
//       }
//   ]
// ------------------------------------------------------------------------------

let data = msg.payload || [];

// Read daytime flag (set elsewhere in the flow)
// const isDaytime = flow.get("daytime") === true;

// Extract alphanumeric camera ID (e.g. NZ0014, NZ001P, NZ002K)
function extractCameraID(topic) {
    let match = topic?.match(/nz[0-9a-z]+/i);
    return match ? match[0].toUpperCase() : (topic || "UNKNOWN");
}

// Group by camera/topic
let seriesMap = {};

for (let entry of data) {
    if (!entry || !entry.topic) continue;

    const label = extractCameraID(entry.topic);
    let value = Number(entry.value_num);

    // 🔸 Force starcount to 0 during daylight
    //if (isDaytime && /\/starcount$/i.test(entry.topic)) {
    //    value = 0;
    //}

    if (!seriesMap[label]) seriesMap[label] = [];
    seriesMap[label].push({
        x: new Date(entry.time),
        y: value
    });
}

// Sort each series by time
for (let label in seriesMap) {
    seriesMap[label].sort((a, b) => a.x - b.x);
}

// Build combined chart payload
msg.payload = [{
    series: Object.keys(seriesMap),
    data: Object.values(seriesMap),
    labels: []
}];

// msg.daylight = isDaytime;  // optional for debug or dashboard text node
return msg;

// ---------- Node-RED Function: Influx result → ui-table (show 0s) ----------
//
// Input: msg.payload = [
//   { topic: "meteorcams/nz0014/nextcapstart", value_str: "2025-10-30 07:12:10 UTC" },
//   { topic: "meteorcams/nz0014/meteorcount",  value_num: 3 },
//   { topic: "meteorcams/nz0014/detectioncount", value_num: 0 },
//   ...
// ]
//
// Output: msg.payload = [
//   { Camera: "NZ0014", "Next Capture": "...", "Meteor Count": 3, "Detection Count": 0 },
//   { Camera: "NZ001P", "Next Capture": "", "Meteor Count": 0, "Detection Count": 0 },
//   ...
// ]
// ---------------------------------------------------------------------------

let data = msg.payload || [];

// Helper — extract the NZ camera ID
function extractCameraID(topic) {
    let match = topic?.match(/nz[0-9a-z]+/i);
    return match ? match[0].toUpperCase() : "UNKNOWN";
}

let grouped = {};

// Pass 1 — create entries for every camera we see
for (let row of data) {
    if (!row || !row.topic) continue;
    const cam = extractCameraID(row.topic);
    if (!grouped[cam]) {
        grouped[cam] = {
            Camera: cam,
            "Next Capture": "",
            "Meteor Count": 0,
            "Detection Count": 0
        };
    }
}

// Pass 2 — populate values
for (let row of data) {
    const cam = extractCameraID(row.topic);
    if (!grouped[cam]) continue;

    if (/nextcapstart$/i.test(row.topic)) {
        grouped[cam]["Next Capture"] = row.value_str || "";
    } 
    else if (/meteorcount$/i.test(row.topic)) {
        grouped[cam]["Meteor Count"] = Number(row.value_num) || 0;
    } 
    else if (/detectioncount$/i.test(row.topic)) {
        grouped[cam]["Detection Count"] = Number(row.value_num) || 0;
    }
}

// Convert to array and sort
msg.payload = Object.values(grouped).sort((a, b) => a.Camera.localeCompare(b.Camera));

return msg;

